$(document).ready(function(){$("#processToPayment").click(function(e){e.preventDefault(),$("#processToPayment").hide();var a=$("#couponCode").val(),o="default";0!=$("#orderType").length&&(o=$("#orderType").val());var r="default";0!=$("#app").length&&(r=$("#app").val());var n=$(".shipping-box").serializeArray();n.push({name:"coupon",value:a}),n.push({name:"type",value:"order"}),n.push({name:"action",value:"generate"}),n.push({name:"order",value:$("#orderId").val()}),n.push({name:"app",value:r}),n.push({name:"pgRequestType",value:o}),n.push({name:"paymentMode",value:$("#paymentMode").val()}),$.ajax({type:"POST",dataType:"json",data:n,success:function(e){200==e.status?window.location.href=e.url:console.log("Success : ",e),$("#processToPayment").show()},error:function(e){console.log("error : ",e),$("#processToPayment").show()}})}),$(".removeFromCart").click(function(e){e.preventDefault();var a=$(this).attr("id");$.ajax({type:"POST",dataType:"json",data:{type:"cart",action:"remove",id:a},success:function(e){200==e.status?location.reload():popUpMessage("center",e.msg,"error"),$("#product_"+a).hide()},error:function(e){console.log(e)}})})});